  str_n31_1_name_desc = "/",
  str_n31_2_name_desc = "Schwartz tem um encontro com o enviado de Northland, Jakine, que chega para reabastecer o Cristal da Memória Eterna com água do Lago Espelho. Você e Mia tropeçar nesta cena por acaso.",
  str_n31_3_name_desc = "Vocês dois descobrem que podem ter entrado na história registrada pelo Cristal da Memória Eterna, mas a situação parece instável...",
  str_n31_4_name_desc = "Você e Mia não são os únicos atraídos para o Cristal da Memória Eterna. Em um canto distante de Lumopolis, dois outros indivíduos também estão encontrando os Eclipsites.",
  str_n31_5_name_desc = "Você segue os guardas até o portão de Lumopolis e fica surpreso ao encontrar um grupo de Eclipsites à espreita entre as mercadorias que chegam.",
  str_n31_6_name_desc = "/",
  str_n31_7_name_desc = "Schwartz pergunta Mia para entrar no duelo na frente de todos. Não querendo apenas fazer um show, Mia pede a seu oponente que não se segure.",
  str_n31_8_name_desc = "O desempenho incrível de Mia no duelo lhe rendeu uma onda de aplausos. Parece que o duelo vai durar um bom tempo.",
  str_n31_9_name_desc = "Durante o duelo, Mia acidentalmente quebra uma caixa de madeira ao seu redor. Mal ela sabe que há surpresas escondidas escondidas dentro...",
  str_n31_10_name_desc = "À medida que a praça central mergulha no caos, as pessoas fogem em todas as direções. Em meio ao tumulto, Sharona dá um passo à frente, oferecendo-se para ajudar Jakine em localizar você e Mia.",
  str_n31_11_name_desc = "Mais Eclipsites emergem dos cantos de Lumopolis, enquanto um grupo de guardas se aproxima de forma ordenada. No entanto, torna-se evidente que eles não são reforços.",
  str_n31_12_name_desc = "/",
  str_n31_13_name_desc = "Seguindo Schwartz, você e Mia chegue ao esconderijo dos rebeldes, onde você encontrará soldados rebeldes à espreita nas sombras, como esperado.",
  str_n31_14_name_desc = "Apoiados contra a parede, os soldados rebeldes estão preparados para uma luta, e parece que também convocaram um formidável aliado...",
  str_n31_15_name_desc = "/",
  str_n31_16_name_desc = "Schwartz lança um olhar significativo para Joshua, cheio de palavras não ditas. Mas o jantar à luz de velas é abruptamente interrompido...",
  str_n31_1_name_desc_long = "Vestindo um caro terno alugado, você se prepara para participar da festa de comemoração do Schwartz Dia da Família em Lumópolis. Quando você está prestes a sair, o esperado Mensageiro de Northland não chega, mas em vez disso, você se cruza com Mia. Ela aparece completamente diferente e, com timidez, confessa seu desejo de encontrar sua família.",
  str_n31_2_name_desc_long = "O enviado do Norte, Jakine, reabastece o Cristal da Memória Eterna com água do Lago Espelho. Ao ouvir que a pessoa que uma vez ativou o Cristal da Memória Eterna não está mais neste mundo, Jakine resolve encontrar outra forma de ajudar Schwartz entrar no reino do Cristal mais uma vez.",
  str_n31_3_name_desc_long = "Você e Mia são trazidos para o mundo do Cristal da Memória Eterna, mas o resto de vocês está faltando. Conforme você explora, você percebe que tropeçou no Schwartz Comemoração do Dia da Família de doze anos atrás. Surpreendentemente, as pessoas ao seu redor abordam Mia como Princesa Veronica com grande reverência.",
  str_n31_4_name_desc_long = "Apesar das objeções de Jakine, Caleb, percebendo que entrou no Cristal da Memória Eterna, toma a decisão de prosseguir sozinho.",
  str_n31_5_name_desc_long = "Caleb conhece sua irmã na mansão de Schwartz, mas ela não o reconhece depois de doze anos. Enquanto isso, você e Mia ajude os guardas no portão de Lumopolis contra um grupo de Eclipsites escondidos entre a carga, onde você é apresentado ao Cavaleiro Capitão Mime Kartima.",
  str_n31_6_name_desc_long = "As dúvidas de Mia desaparecem quando ela põe os olhos em sua mãe, Joshua e irmã. Carleen. Os sonhos vívidos em sua mente não são mais seus próprios delírios. Mia finalmente aceita a verdade de que ela já foi a princesa Veronica.",
  str_n31_7_name_desc_long = "Uma mulher bêbada zomba das habilidades de adivinhação de Jakine e localiza você e Mia para Jakine durante o desfile de carruagens. No entanto, devido à distância, você não pode ver Jakine. Depois do desfile, Schwartz insiste que Mia junte-se ao ritual de duelo e é então que você vê a determinação inabalável de Mia pela primeira vez.",
  str_n31_8_name_desc_long = "Impulsionado por sua intenção de roubar o Cristal da Memória Eterna do mundo, Caleb rapidamente incapacita os guardas da mansão de Schwartz. Enquanto isso, Jakine vê-se compelida a acreditar que a mulher aparentemente discreta diante dela é de fato sua própria mãe.",
  str_n31_9_name_desc_long = "Dentro do Cristal da Memória Eterna, Schwartz finalmente conhece você. Ele te culpa por deixar Mia correr o risco de participar do duelo. No entanto, como você vê Mia prestes a vencer o duelo, você não consegue entender por que Schwartz ainda está tão preocupado.",
  str_n31_10_name_desc_long = "Schwartz quer fugir da área infestada de Eclipsite com Mia e você, mas ele é contido por Schwartz de dentro do Cristal da Memória Eterna. Apesar do intervalo de apenas doze anos entre os dois Schwartz, eles não têm mais nenhuma semelhança um com o outro.",
  str_n31_11_name_desc_long = "Jakine está finalmente reunido com você, mas a situação à frente parece sombria. Eclipsites continuam a surgir, e outra facção de rebeldes está diante de você. Finalmente fica claro por que Schwartz tem sido inflexível em manter Mia e você longe do Schwartz deste mundo.",
  str_n31_12_name_desc_long = "Apesar de ter sido esfaqueado, Schwartz de dentro do Cristal da Memória Eterna consegue afastar os rebeldes com a ajuda da multidão. Torna-se evidente que Mime Kartima é o cérebro por trás da rebelião. Enquanto Schwartz deseja proteger Mia de reviver essa história, sua determinação de descobrir a verdade permanece inabalável.",
  str_n31_13_name_desc_long = "Ao descobrir o esconderijo dos rebeldes, Schwartz dentro do Cristal da Memória Eterna instrui Mia para alcançar a vitória por todos os meios necessários, uma postura que você não pode endossar. Enquanto isso, o outro Schwartz expressa sua esperança de que você possa encontrar um caminho alternativo.",
  str_n31_14_name_desc_long = "Mime Kartima convoca um dragão voador para ajudar, mas Schwartz notavelmente luta contra o dragão sozinho. No fim, Schwartz põe fim à rebelião, como esperado.",
  str_n31_15_name_desc_long = "Com o período mais perigoso para trás, Schwartz finalmente revela seu lado gentil raramente visto. Jakine emprega magia para restaurar Schwartz à sua aparência juvenil, concedendo-lhe a oportunidade de se despedir de Joshua, a quem ele nunca foi capaz de deixar ir de seu coração.",
  str_n31_16_name_desc_long = "Sem aviso, o mundo do Cristal da Memória Eterna desmorona abruptamente em uma pequena ilha, com uma sombra perseguindo você implacavelmente. À medida que o sino da meia-noite toca, a pergunta urgente persiste: todos escaparão ilesos do Cristal da Memória Eterna?",
