  str_n31_h12_name = "EX6 - Vanguarda",
  str_n31_h1_name_desc = "Na jornada, os obstáculos abundam como espinhos. Mas com determinação inabalável, podemos curar rapidamente as feridas ao longo do caminho.",
  str_n31_h2_name_desc = "Ataques normais não resolverão o problema. É hora de liberar suas habilidades poderosas.",
  str_n31_h3_name_desc = "Se você não conseguir avançar pela frente, pode valer a pena tentar uma abordagem lateral, mesmo que isso signifique fazer um longo desvio...",
  str_n31_h4_name_desc = "O calor escaldante intensifica a batalha, representando um risco maior para todos os envolvidos.",
  str_n31_h5_name_desc = "Fique atento às armadilhas, mas lembre-se também de aproveitar todas as oportunidades que elas possam apresentar.",
  str_n31_h6_name_desc = "Os ataques do inimigo vêm como ondas implacáveis. Esforce-se para enfraquecê-lo e derrotá-lo antes do próximo ataque.",
